      { text: "C", options: { bold: true, color: C.darkBg, fontSize: 9 } },
      { text: "2", options: { bold: true, color: C.darkBg, fontSize: 9, align: "center" } },
      "1", "2", "2", "2", "1", "1", "1", "1"
    ],
    ["C++",  "3",  "4", "3", "3", "3", "2", "2", "2", "9" ],
    ["Java", "4",  "2", "1", "1", "1", "3", "31","—", "—" ],
    ["C#",   "5",  "5", "4", "5", "7", "11","—", "—", "—" ],
    ["JS",   "6",  "7", "8", "10","10","8", "33","—", "—" ],
    ["Go",   "10", "11","60","16","—", "—", "—", "—", "—" ],
    ["Ada",  "14", "36","25","22","16","18","6", "10", "3" ],
    ["Lisp", "26", "34","26","13","14","19","8", "4",  "2" ],
  ];

  s.addTable(histTable, {
    x: 0.35, y: 1.0, w: 9.3, h: 2.8,
    colW: [1.0, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8],
    border: { pt: 0.3, color: "CBD5E1" },
    fontFace: FONT_BODY,
    fontSize: 9,
    color: "1E293B",
    valign: "middle",
    align: "center",
  });

  // ── Historical trend callouts ──────────────────────────────────────────────────
  const callouts = [
    {
      title: "C: The Unshakeable Constant",
      body: "The only language to hold top-2 across all nine measurement points from 1986 to 2026. From #1 in 1986 to #2 in 2026.",
      color: C.darkBg, accent: C.teal
    },
    {
      title: "Python's 25-Year Ascent",
      body: "Unranked in 1986, outside top 30 in 2001, top 10 by 2006, #1 by 2021 — a 25-year journey from obscurity to dominance.",
      color: C.cardBg, accent: C.green
    },
    {
      title: "Java's Long Decline",
      body: "Peaked at 25%+ (2005–2018) dominating the index. Now at sub-8% as cloud and scripting languages erode its lead.",
      color: C.cardBg, accent: C.red
    },
    {
      title: "Lisp: From #2 to #26",
      body: "The language that pioneered AI research now ranks 26th — a cautionary tale of ecosystem lock-in vs. market evolution.",
      color: C.cardBg, accent: C.gold
    },
  ];

  let cx = 0.35;
  callouts.forEach((c, i) => {
    const cw = 2.2;
    s.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: 3.95, w: cw, h: 1.45,
      fill: { color: c.color }, line: { color: c.accent, width: 1.5 },
      shadow: makeShadow()
    });
    // Top accent
    s.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: 3.95, w: cw, h: 0.06,
      fill: { color: c.accent }
    });
    s.addText(c.title, {
      x: cx + 0.12, y: 4.08, w: cw - 0.24, h: 0.4,
      fontSize: 9, bold: true, color: i === 0 ? C.white : C.white,
      fontFace: FONT_BODY, align: "left", valign: "top", margin: 0
    });
    s.addText(c.body, {
      x: cx + 0.12, y: 4.48, w: cw - 0.24, h: 0.85,
      fontSize: 8, color: C.slate, fontFace: FONT_BODY,
      align: "left", valign: "top", margin: 0
    });
    cx += cw + 0.1;
  });
}

// ═══════════════════════════════════════════════════════════════════════════════
// SLIDE 5 — HALL OF FAME
// ═══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.darkBg };

  // Header
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.9, fill: { color: C.cardBg } });
  s.addText("Python Wins Language of the Year 6 Times — More Than Any Other Language", {
    x: 0.4, y: 0, w: 9.2, h: 0.9,
    fontSize: 20, bold: true, color: C.white,
    fontFace: FONT_TITLE, align: "left", valign: "middle", margin: 0
  });

  // Subtitle
  s.addText("Awarded annually to the language with the largest gain in TIOBE ratings during a calendar year", {
    x: 0.4, y: 1.0, w: 9, h: 0.35,
    fontSize: 11, color: C.slate, fontFace: FONT_BODY, align: "left", margin: 0, italic: true
  });

  // ── Hall of Fame timeline ─────────────────────────────────────────────────────
  const winners = [
    { year: "2025", lang: "C#",      color: "6D28D9", note: ".NET ecosystem momentum" },
    { year: "2024", lang: "Python",   color: C.teal,    note: "AI/ML dominance continues" },
    { year: "2023", lang: "C#",       color: "7C3AED",  note: "Cross-platform .NET growth" },
    { year: "2022", lang: "C++",      color: "0891B2", note: "Systems programming revival" },
    { year: "2021", lang: "Python",   color: C.teal,    note: "Data science & automation wave" },
    { year: "2020", lang: "Python",   color: C.teal,    note: "ML & quick scripting adoption" },
    { year: "2019", lang: "C",        color: "475569",  note: "Embedded & IoT surge" },
    { year: "2018", lang: "Python",   color: C.teal,    note: "Deep learning breakthrough" },
    { year: "2016", lang: "Go",       color: "0EA5E9",  note: "Cloud-native adoption" },
  ];

  // Draw timeline spine
  const startX = 0.7;
  const endX = 9.3;
  s.addShape(pres.shapes.LINE, {
    x: startX, y: 2.55, w: endX - startX, h: 0,
    line: { color: C.slate, width: 1, transparency: 60 }
  });

  // Winner cards along timeline
  winners.forEach((w, i) => {
    const tx = startX + (i / (winners.length - 1)) * (endX - startX);
    const isPython = w.lang === "Python";

    // Dot on timeline
    s.addShape(pres.shapes.OVAL, {
      x: tx - 0.12, y: 2.43, w: 0.24, h: 0.24,
      fill: { color: w.color }, line: { color: C.darkBg, width: 2 }
    });

    // Year label (alternating above/below)
    const above = i % 2 === 0;
    const labelY = above ? 1.85 : 2.75;

    // Connector line
    s.addShape(pres.shapes.LINE, {
      x: tx, y: above ? 2.42 : 2.67, w: 0, h: above ? labelY - 2.42 : 2.75 - 2.67,
      line: { color: w.color, width: 0.8, transparency: 50 }
    });

    // Year badge
    s.addShape(pres.shapes.RECTANGLE, {
      x: tx - 0.35, y: labelY, w: 0.7, h: 0.3,
      fill: { color: w.color }
    });
    s.addText(w.year, {
      x: tx - 0.35, y: labelY, w: 0.7, h: 0.3,
      fontSize: 9, bold: true, color: C.white,
      fontFace: FONT_BODY, align: "center", valign: "middle", margin: 0
    });

    // Language name
    const nameY = above ? labelY - 0.42 : labelY + 0.33;
    s.addText(w.lang, {
      x: tx - 0.55, y: nameY, w: 1.1, h: 0.32,
      fontSize: isPython ? 13 : 11, bold: true, color: isPython ? C.tealMuted : C.white,
      fontFace: FONT_BODY, align: "center", valign: "middle", margin: 0
    });

    // Note below dot
    const noteY = above ? nameY + 0.35 : nameY - 0.35;
    s.addText(w.note, {
      x: tx - 0.65, y: noteY, w: 1.3, h: 0.28,
      fontSize: 7, color: C.slate, fontFace: FONT_BODY,
      align: "center", valign: "middle", margin: 0
    });
  });

  // ── Bottom stat cards ─────────────────────────────────────────────────────────
  const stats = [
    { value: "6×", label: "Python wins", sub: "2007, 2010, 2018, 2020, 2021, 2024" },
    { value: "2×", label: "C# wins",    sub: "2023 & 2025 — recent momentum" },
    { value: "9 yrs", label: "since Go's win", sub: "2016 winner now at 16th rank" },
  ];

  let sx = 0.4;
  stats.forEach((st) => {
    s.addShape(pres.shapes.RECTANGLE, {
      x: sx, y: 4.4, w: 3.0, h: 0.95,
      fill: { color: C.cardBg }, line: { color: C.teal, width: 1 },
      shadow: makeShadow()
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: sx, y: 4.4, w: 0.06, h: 0.95,
      fill: { color: C.teal }
    });
    s.addText(st.value, {
      x: sx + 0.15, y: 4.42, w: 1.1, h: 0.55,
      fontSize: 26, bold: true, color: C.tealMuted,
      fontFace: FONT_TITLE, align: "left", valign: "middle", margin: 0
    });
    s.addText(st.label, {
      x: sx + 1.2, y: 4.45, w: 1.7, h: 0.3,
      fontSize: 11, bold: true, color: C.white,
      fontFace: FONT_BODY, align: "left", valign: "middle", margin: 0
    });
    s.addText(st.sub, {
      x: sx + 1.2, y: 4.75, w: 1.7, h: 0.3,
      fontSize: 8, color: C.slate, fontFace: FONT_BODY,
      align: "left", valign: "top", margin: 0
    });
    sx += 3.15;
  });
}

// ═══════════════════════════════════════════════════════════════════════════════
// SLIDE 6 — TAKEAWAYS
// ═══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.offWhite };

  // Header
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.9, fill: { color: C.darkBg } });
  s.addText("The Top 4 Languages Hold 49% of the Index: What This Means for Your Tech Stack", {
    x: 0.4, y: 0, w: 9.2, h: 0.9,
    fontSize: 18, bold: true, color: C.white,
    fontFace: FONT_TITLE, align: "left", valign: "middle", margin: 0
  });

  // Left column: Key findings
  const findings = [
    {
      icon: "1",
      title: "Python's Dominance vs. Decline Trajectory",
      body: "21.25% rating — more than double C — but posting the largest YoY drop (−2.59 pts) among the top 5. AI/ML demand sustains it, yet growth has plateaued. Don't assume continued linear rise."
    },
    {
      icon: "2",
      title: "C's Resurgence — A Structural Shift",
      body: "C surged to #2 (+2.02 pts YoY), the largest absolute gain in the top 20. This aligns with IoT, embedded systems, and security-critical infrastructure growth — not a cyclical blip."
    },
    {
      icon: "3",
      title: "Legacy Language Revival Is Real",
      body: "Perl (+13 ranks), R (+7 ranks), and Fortran (holding top 15) show entrenched scientific and data communities aren't shrinking — they're just quiet. Factor them into hiring for specialized roles."
    },
    {
      icon: "4",
      title: "Go's Fall Is a Warning Sign",
      body: "Go fell from 7th to 16th — the biggest rank drop in the index. Rust's steady presence at 14th suggests systems programming mindshare is being redistributed. Reassess Go-centric investments."
    },
  ];

  let fy = 1.1;
  findings.forEach((f) => {
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.35, y: fy, w: 5.7, h: 0.95,
      fill: { color: C.white }, line: { color: "E2E8F0", width: 0.75 },
      shadow: makeShadow()
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.35, y: fy, w: 0.06, h: 0.95,
      fill: { color: C.teal }
    });
    s.addShape(pres.shapes.OVAL, {
      x: 0.52, y: fy + 0.18, w: 0.5, h: 0.5,
      fill: { color: C.teal }
    });
    s.addText(f.icon, {
      x: 0.52, y: fy + 0.18, w: 0.5, h: 0.5,
      fontSize: 14, bold: true, color: C.white,
      fontFace: FONT_BODY, align: "center", valign: "middle", margin: 0
    });
    s.addText(f.title, {
      x: 1.15, y: fy + 0.07, w: 4.75, h: 0.32,
      fontSize: 10, bold: true, color: C.darkBg,
      fontFace: FONT_BODY, align: "left", valign: "middle", margin: 0
    });
    s.addText(f.body, {
      x: 1.15, y: fy + 0.4, w: 4.75, h: 0.5,
      fontSize: 8.5, color: "475569", fontFace: FONT_BODY,
      align: "left", valign: "top", margin: 0
    });
    fy += 1.07;
  });

  // Right column: Concentration risk visualization
  s.addShape(pres.shapes.RECTANGLE, {
    x: 6.25, y: 1.1, w: 3.4, h: 2.8,
    fill: { color: C.darkBg }, line: { color: C.teal, width: 1 },
    shadow: makeShadow()
  });
  s.addText("Index Concentration", {
    x: 6.35, y: 1.2, w: 3.2, h: 0.35,
    fontSize: 11, bold: true, color: C.white,
    fontFace: FONT_BODY, align: "center", valign: "middle", margin: 0
  });

  const pieData = [{
    name: "Share",
    labels: ["Python 21%", "C 12%", "C++ 8%", "Java 8%", "C# 6%", "Others 45%"],
    values: [21.25, 11.55, 8.18, 7.99, 6.36, 44.67]
  }];

  s.addChart(pres.charts.DOUGHNUT, pieData, {
    x: 6.25, y: 1.55, w: 3.4, h: 2.2,
    chartColors: [C.teal, C.tealLight, "0891B2", "64748B", "94A3B8", "CBD5E1"],
    showPercent: false,
    showValue: false,
    showLegend: false,
    holeSize: 55,
  });

  // Center label in donut
  s.addText("49%", {
    x: 6.25, y: 2.35, w: 3.4, h: 0.6,
    fontSize: 32, bold: true, color: C.tealMuted,
    fontFace: FONT_TITLE, align: "center", valign: "middle", margin: 0
  });
  s.addText("Top 4", {
    x: 6.25, y: 2.85, w: 3.4, h: 0.3,
    fontSize: 10, color: C.slate, fontFace: FONT_BODY,
    align: "center", valign: "middle", margin: 0
  });

  // Bottom recommendation box
  s.addShape(pres.shapes.RECTANGLE, {
    x: 6.25, y: 4.05, w: 3.4, h: 1.3,
    fill: { color: C.cardBg }, line: { color: C.gold, width: 1.5 },
    shadow: makeShadow()
  });
  s.addShape(pres.shapes.RECTANGLE, {
    x: 6.25, y: 4.05, w: 3.4, h: 0.06,
    fill: { color: C.gold }
  });
  s.addText("Strategic Implication", {
    x: 6.4, y: 4.18, w: 3.1, h: 0.3,
    fontSize: 10, bold: true, color: C.gold,
    fontFace: FONT_BODY, align: "left", valign: "middle", margin: 0
  });
  s.addText("Concentration risk is real — nearly half the index is top-4 languages. A diversified stack hedge (Python for AI, C for systems, C#/.NET for enterprise) balances momentum with stability.", {
    x: 6.4, y: 4.5, w: 3.1, h: 0.8,
    fontSize: 9, color: C.offWhite, fontFace: FONT_BODY,
    align: "left", valign: "top", margin: 0
  });
}

// ── Write output ─────────────────────────────────────────────────────────────────
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("✅  /app/output/final_deck.pptx written"))
  .catch(e => { console.error(e); process.exit(1); });

