const pptxgen = require("pptxgenjs");

// ── Palette: Midnight Executive with teal accent ─────────────────────────────────
const C = {
  darkBg:    "0F172A",   // near-black navy
  cardBg:    "1E293B",   // slate card
  cardBg2:   "283A5E",   // lighter card
  teal:      "0D9488",   // primary accent
  tealLight: "14B8A6",   // lighter teal
  tealMuted: "5EEAD4",   // very light teal
  white:     "FFFFFF",
  offWhite:  "F1F5F9",
  slate:     "94A3B8",
  red:       "EF4444",   // loser accent
  green:     "22C55E",   // winner/gainer accent
  gold:      "F59E0B",   // highlight
};

// ── Helpers ─────────────────────────────────────────────────────────────────────
const FONT_TITLE = "Trebuchet MS";
const FONT_BODY  = "Calibri";

function makeShadow() {
  return { type: "outer", color: "000000", blur: 8, offset: 3, angle: 135, opacity: 0.25 };
}

// ── Presentation ───────────────────────────────────────────────────────────────
const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title  = "TIOBE Index March 2026";
pres.author = "Data Analysis";

// ═══════════════════════════════════════════════════════════════════════════════
// SLIDE 1 — TITLE
// ═══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.darkBg };

  // Top accent bar
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.08, fill: { color: C.teal } });

  // Left vertical accent stripe
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.07, h: 5.625, fill: { color: C.teal } });

  // "TIOBE INDEX" label chip
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 1.2, w: 1.9, h: 0.42,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  s.addText("TIOBE INDEX", {
    x: 0.6, y: 1.2, w: 1.9, h: 0.42,
    fontSize: 11, bold: true, color: C.white,
    fontFace: FONT_BODY, align: "center", valign: "middle", margin: 0,
    charSpacing: 2
  });

  // Main title
  s.addText("March 2026", {
    x: 0.6, y: 1.78, w: 8.5, h: 0.9,
    fontSize: 48, bold: true, color: C.white,
    fontFace: FONT_TITLE, align: "left", valign: "bottom", margin: 0
  });

  // Subtitle line 1
  s.addText("Programming Language Popularity Rankings", {
    x: 0.6, y: 2.68, w: 8.5, h: 0.52,
    fontSize: 24, color: C.tealMuted,
    fontFace: FONT_TITLE, align: "left", valign: "top", margin: 0
  });

  // Thin divider
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 3.38, w: 3.2, h: 0.03,
    fill: { color: C.teal }
  });

  // Methodology note
  s.addText("Ratings based on search-engine hit counts across Google, Bing, Wikipedia, Amazon, and 20+ other sites — reflecting global engineer interest, not code volume.", {
    x: 0.6, y: 3.55, w: 7.2, h: 0.7,
    fontSize: 12, color: C.slate, fontFace: FONT_BODY,
    align: "left", valign: "top", margin: 0
  });

  // Bottom tagline
  s.addText("Software Engineering Leads & Technology Strategists", {
    x: 0.6, y: 5.1, w: 6, h: 0.3,
    fontSize: 10, color: C.slate, fontFace: FONT_BODY,
    align: "left", margin: 0, charSpacing: 1
  });

  // Right side decorative circles (abstract data viz feel)
  s.addShape(pres.shapes.OVAL, {
    x: 7.8, y: 0.8, w: 2.2, h: 2.2,
    fill: { color: C.teal, transparency: 15 }, line: { color: C.teal, width: 1, transparency: 40 }
  });
  s.addShape(pres.shapes.OVAL, {
    x: 8.3, y: 2.4, w: 1.6, h: 1.6,
    fill: { color: C.tealLight, transparency: 20 }, line: { color: C.tealLight, width: 1, transparency: 50 }
  });
  s.addShape(pres.shapes.OVAL, {
    x: 7.5, y: 3.4, w: 1.0, h: 1.0,
    fill: { color: C.tealMuted, transparency: 25 }, line: { color: C.tealMuted, width: 1, transparency: 60 }
  });
}

// ═══════════════════════════════════════════════════════════════════════════════
// SLIDE 2 — TOP 20 RANKINGS  (table + bar chart)
// ═══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.offWhite };

  // Header bar
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.9, fill: { color: C.darkBg } });
  s.addText("Python Holds #1 at 21.25% but C Surges to #2 with the Largest Gain", {
    x: 0.4, y: 0, w: 9.2, h: 0.9,
    fontSize: 20, bold: true, color: C.white,
    fontFace: FONT_TITLE, align: "left", valign: "middle", margin: 0
  });

  // ── Left: Table ──────────────────────────────────────────────────────────────
  const tableData = [
    // Header
    [
      { text: "#", options: { bold: true, color: C.white, fill: { color: C.darkBg }, fontSize: 9, align: "center" } },
      { text: "Lang", options: { bold: true, color: C.white, fill: { color: C.darkBg }, fontSize: 9, align: "left" } },
      { text: "Rating", options: { bold: true, color: C.white, fill: { color: C.darkBg }, fontSize: 9, align: "right" } },
      { text: "YoY", options: { bold: true, color: C.white, fill: { color: C.darkBg }, fontSize: 9, align: "center" } },
    ],
    // Rows 1-10
    ["1", "Python",      "21.25%", "+4.25%"],
    [{ text: "2", options: { color: C.teal, bold: true } }, { text: "C", options: { color: C.teal, bold: true } }, { text: "11.55%", options: { color: C.teal, bold: true } }, { text: "+2.02%", options: { color: C.teal, bold: true } }],
    ["3", "C++",         "8.18%",  "−2.90%"],
    ["4", "Java",        "7.99%",  "−2.37%"],
    [{ text: "5", options: { color: C.teal } }, { text: "C#", options: { color: C.teal } }, { text: "6.36%", options: { color: C.teal } }, { text: "+1.49%", options: { color: C.teal } }],
    ["6", "JavaScript",  "3.45%",  "−0.01%"],
    ["7", "VB",          "2.50%",  "−0.02%"],
    ["8", "SQL",         "2.00%",  "−0.57%"],
    [{ text: "9", options: { color: C.teal } }, { text: "R", options: { color: C.teal } }, { text: "1.88%", options: { color: C.teal } }, { text: "+0.94%", options: { color: C.teal } }],
    ["10","Delphi",      "1.80%",  "−0.36%"],
    // Spacer row label
    [
      { text: "▲ RISERS", options: { bold: true, color: C.teal, fill: { color: C.darkBg }, fontSize: 9, colspan: 4 } }
    ],
    // Rows 11-20
    [{ text: "11", options: { color: C.teal, bold: true } }, { text: "Perl", options: { color: C.teal, bold: true } }, { text: "1.75%", options: { color: C.teal } }, { text: "+1.05%", options: { color: C.teal } }],
    ["12","Scratch",     "1.63%",  "−0.03%"],
    ["13","Fortran",     "1.45%",  "−0.25%"],
